//! The embedded ship database and image decoding.

use eframe::egui::ColorImage;
use serde::{Deserialize, Deserializer};

/// `assets/ships.json`, compiled into the executable.
const SHIPS_JSON: &str = include_str!("../assets/ships.json");

// Generated by build.rs: `embedded_image(name)` and `EMBEDDED_IMAGE_COUNT`.
include!(concat!(env!("OUT_DIR"), "/embedded_images.rs"));

/// Images wider than this are downscaled after decoding to keep the GPU
/// texture small. Bundled images are 800 px wide, so this is only a guard
/// for replacement images.
const MAX_TEXTURE_WIDTH: u32 = 1600;

#[derive(Debug, Clone, Deserialize)]
pub struct Ship {
    pub id: String,
    pub name: String,
    pub nation: String,
    pub class: String,
    /// A year (`1765`) or free text (`"Unknown (15th century)"`).
    #[serde(deserialize_with = "year_or_text")]
    pub launched: String,
    pub fate: String,
    pub description: String,
    pub fun_fact: String,
    /// File name inside `assets/images/`.
    pub image: String,
    /// Short attribution shown on the photo. Full details are in LICENSES.md.
    #[serde(default)]
    pub image_credit: String,
    /// Point of interest in the photo (x, y in 0..=1), kept in view when the
    /// photo is cropped to fit the card.
    #[serde(default = "centre")]
    pub focus: [f32; 2],
}

fn centre() -> [f32; 2] {
    [0.5, 0.5]
}

fn year_or_text<'de, D: Deserializer<'de>>(deserializer: D) -> Result<String, D::Error> {
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum YearOrText {
        Year(i64),
        Text(String),
    }
    Ok(match YearOrText::deserialize(deserializer)? {
        YearOrText::Year(year) => year.to_string(),
        YearOrText::Text(text) => text,
    })
}

/// Parses the embedded database.
pub fn load() -> Result<Vec<Ship>, String> {
    parse(SHIPS_JSON)
}

/// Parses a ship database, dropping unusable entries (blank id or name,
/// duplicate ids). Fails on invalid JSON or when no usable ship remains.
pub fn parse(json: &str) -> Result<Vec<Ship>, String> {
    let mut ships: Vec<Ship> = serde_json::from_str(json)
        .map_err(|err| format!("The ship database is not valid: {err}"))?;

    let mut seen_ids: Vec<String> = Vec::with_capacity(ships.len());
    ships.retain(|ship| {
        let usable = !ship.id.trim().is_empty()
            && !ship.name.trim().is_empty()
            && !seen_ids.contains(&ship.id);
        if usable {
            seen_ids.push(ship.id.clone());
        }
        usable
    });

    if ships.is_empty() {
        return Err("The ship database contains no ships.".to_owned());
    }
    Ok(ships)
}

/// Decodes the embedded photo of one ship. Only ever called for the ship
/// that is about to be displayed.
pub fn decode_image(ship: &Ship) -> Result<ColorImage, String> {
    let bytes = embedded_image(&ship.image)
        .ok_or_else(|| format!("image '{}' is not embedded in this build", ship.image))?;
    decode_jpeg(bytes).map_err(|err| format!("image '{}' could not be decoded: {err}", ship.image))
}

fn decode_jpeg(bytes: &[u8]) -> Result<ColorImage, String> {
    let mut decoded = image::load_from_memory_with_format(bytes, image::ImageFormat::Jpeg)
        .map_err(|err| err.to_string())?;
    if decoded.width() == 0 || decoded.height() == 0 {
        return Err("image has no pixels".to_owned());
    }
    if decoded.width() > MAX_TEXTURE_WIDTH {
        let height = (u64::from(decoded.height()) * u64::from(MAX_TEXTURE_WIDTH)
            / u64::from(decoded.width()))
        .max(1) as u32;
        decoded = decoded.resize_exact(
            MAX_TEXTURE_WIDTH,
            height,
            image::imageops::FilterType::Triangle,
        );
    }
    let rgb = decoded.into_rgb8();
    let size = [rgb.width() as usize, rgb.height() as usize];
    Ok(ColorImage::from_rgb(size, rgb.as_raw()))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn database_is_valid_and_large_enough() {
        let ships = load().expect("ships.json must parse");
        assert!(
            ships.len() >= 20,
            "expected at least 20 ships, got {}",
            ships.len()
        );
        for ship in &ships {
            for (field, value) in [
                ("nation", &ship.nation),
                ("class", &ship.class),
                ("launched", &ship.launched),
                ("fate", &ship.fate),
                ("description", &ship.description),
                ("fun_fact", &ship.fun_fact),
                ("image", &ship.image),
                ("image_credit", &ship.image_credit),
            ] {
                assert!(!value.trim().is_empty(), "{}: '{field}' is empty", ship.id);
            }
            assert!(
                ship.focus.iter().all(|v| (0.0..=1.0).contains(v)),
                "{}: focus must be within 0..=1",
                ship.id
            );
        }
    }

    #[test]
    fn ids_are_unique() {
        let raw: Vec<Ship> = serde_json::from_str(SHIPS_JSON).unwrap();
        assert_eq!(
            raw.len(),
            load().unwrap().len(),
            "duplicate or blank ids in ships.json"
        );
    }

    /// The card has fixed dimensions; these limits keep every text inside it.
    #[test]
    fn texts_fit_the_card() {
        for ship in load().unwrap() {
            let len = |s: &str| s.chars().count();
            assert!(len(&ship.name) <= 26, "{}: name too long", ship.id);
            assert!(len(&ship.class) <= 46, "{}: class too long", ship.id);
            assert!(len(&ship.fate) <= 80, "{}: fate too long", ship.id);
            assert!(
                len(&ship.description) <= 230,
                "{}: description too long",
                ship.id
            );
            assert!(len(&ship.fun_fact) <= 180, "{}: fun_fact too long", ship.id);
            assert!(
                len(&ship.image_credit) <= 82,
                "{}: image_credit too long",
                ship.id
            );
        }
    }

    #[test]
    fn every_ship_image_is_embedded_and_decodes() {
        for ship in load().unwrap() {
            let image = decode_image(&ship).unwrap_or_else(|err| panic!("{}: {err}", ship.id));
            assert!(
                image.size[0] >= 400,
                "{}: image is narrower than 400 px",
                ship.id
            );
        }
        let embedded = EMBEDDED_IMAGE_COUNT;
        assert!(embedded >= 20, "only {embedded} images are embedded");
    }

    #[test]
    fn bad_databases_are_rejected_not_fatal() {
        assert!(parse("not json").is_err());
        assert!(parse("[]").is_err());
        assert!(parse(r#"[{"id": "x"}]"#).is_err());
        assert!(decode_jpeg(b"definitely not a jpeg").is_err());
    }
}
